"use client";

import { useReducedMotion, type Transition } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Kbd } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { SearchIcon } from "./icons";
import { CommandPalette, type PaletteBox } from "./settings-command/command-palette";
import { ROWS, searchRows, SECTIONS, type SettingValues, START_VALUES } from "./settings-command/data";
import { SettingRow } from "./settings-command/setting-row";

type Phase = "closed" | "open" | "flying" | "closing";

// Critically damped, so the palette lands without a wobble.
const GROW: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
const FLY: Transition = { type: "spring", stiffness: 300, damping: 35, mass: 1, opacity: { duration: 0.3, delay: 0.2 } };
const INSTANT: Transition = { duration: 0 };

/** A rem in pixels, for boxes measured from the page. */
const REM = 16;

const isTyping = (target: EventTarget) =>
  target instanceof HTMLElement && (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));

/** The box of `element` measured from the top left of `container`. */
function boxOf(element: Element, container: Element, borderRadius: number, opacity = 1): PaletteBox {
  const a = element.getBoundingClientRect();
  const b = container.getBoundingClientRect();
  return { top: a.top - b.top, left: a.left - b.left, width: a.width, height: a.height, borderRadius, opacity };
}

/**
 * Workspace settings with a search field in the header. The field grows into
 * a palette; picking a result flies the palette into its row while the list
 * scrolls there, then the row glows for a moment. Slash, or Command or Control
 * with K, opens the search while focus is inside the block.
 */
export function SettingsCommand({ className }: { className?: string }) {
  const [values, setValues] = useState<SettingValues>(START_VALUES);
  const [phase, setPhase] = useState<Phase>("closed");
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [boxes, setBoxes] = useState<{ from: PaletteBox; to: PaletteBox; width: number } | null>(null);
  const [section, setSection] = useState(SECTIONS[0]!.id);
  const [washed, setWashed] = useState<string | null>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const landing = useRef<string | null>(null);
  const washTimer = useRef<number | null>(null);
  const titleId = useId();
  const reduceMotion = useReducedMotion();

  const results = searchRows(query);

  useEffect(() => () => {
    if (washTimer.current) window.clearTimeout(washTimer.current);
  }, []);

  const land = (rowId: string) => {
    const row = scrollRef.current?.querySelector<HTMLElement>(`[data-row-id="${rowId}"]`);
    row?.querySelector<HTMLElement>("input, button, [role='combobox']")?.focus({ preventScroll: true });
    setWashed(rowId);
    if (washTimer.current) window.clearTimeout(washTimer.current);
    washTimer.current = window.setTimeout(() => setWashed(null), 1100);
  };

  const open = () => {
    const stage = stageRef.current;
    const trigger = triggerRef.current;
    if (!stage || !trigger || phase !== "closed") return;
    const width = Math.min(stage.clientWidth - 1.5 * REM, 35 * REM);
    const from = boxOf(trigger, stage, 0.5 * REM);
    const to = { top: 0.75 * REM, left: (stage.clientWidth - width) / 2, width, height: Math.min(25 * REM, stage.clientHeight - 1.5 * REM), borderRadius: REM, opacity: 1 };
    setBoxes({ from, to, width });
    setQuery("");
    setActive(0);
    setPhase("open");
  };

  const close = () => {
    const stage = stageRef.current;
    const trigger = triggerRef.current;
    if (!stage || !trigger || !boxes) return;
    setBoxes({ ...boxes, to: boxOf(trigger, stage, 0.5 * REM, 0) });
    setPhase("closing");
  };

  const pick = (index: number) => {
    const target = results[index];
    const stage = stageRef.current;
    const box = scrollRef.current;
    const row = box?.querySelector<HTMLElement>(`[data-row-id="${target?.id}"]`);
    if (!target || !stage || !box || !row || !boxes) return;
    // Scroll the row near the top, and aim the palette where the row will be once the scroll ends.
    const goal = Math.max(0, Math.min(row.offsetTop - REM, box.scrollHeight - box.clientHeight));
    const landingBox = boxOf(row, stage, 0.75 * REM, 0);
    landingBox.top -= goal - box.scrollTop;
    box.scrollTo({ top: goal, behavior: reduceMotion ? "auto" : "smooth" });
    landing.current = target.id;
    setBoxes({ ...boxes, to: landingBox });
    setPhase("flying");
  };

  const settle = () => {
    if (phase === "flying" && landing.current) {
      land(landing.current);
      landing.current = null;
      setPhase("closed");
    } else if (phase === "closing") {
      setPhase("closed");
      triggerRef.current?.focus();
    }
  };

  const onKeyDown = (event: KeyboardEvent) => {
    const shortcut = (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k";
    if (shortcut || (event.key === "/" && !isTyping(event.target))) {
      event.preventDefault();
      open();
    }
  };

  const onScroll = () => {
    const box = scrollRef.current;
    if (!box) return;
    const heads = [...box.querySelectorAll<HTMLElement>("[data-section-id]")];
    const current = heads.filter((head) => head.offsetTop <= box.scrollTop + 2 * REM).pop() ?? heads[0];
    if (current?.dataset.sectionId) setSection(current.dataset.sectionId);
  };

  const jumpTo = (id: string) => {
    const box = scrollRef.current;
    const head = box?.querySelector<HTMLElement>(`[data-section-id="${id}"]`);
    if (box && head) box.scrollTo({ top: head.offsetTop - 0.5 * REM, behavior: reduceMotion ? "auto" : "smooth" });
    setSection(id);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className} onKeyDown={onKeyDown}>
      <div ref={stageRef} className="relative">
        <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Workspace settings
            </h2>
            <p className="text-sm text-muted-foreground">Fernhill Physio Group, 3 clinics</p>
          </div>
          <Button
            ref={triggerRef}
            variant="outline"
            onClick={open}
            aria-haspopup="dialog"
            aria-keyshortcuts="/ Control+K Meta+K"
            className={cn("w-full justify-start @md:w-64", phase !== "closed" && "invisible")}
          >
            <SearchIcon aria-hidden="true" className="size-4 text-muted-foreground" />
            <span className="text-muted-foreground">Search settings</span>
            <Kbd aria-hidden="true" className="ml-auto">
              /
            </Kbd>
          </Button>
        </header>

        <div className="grid @2xl:grid-cols-[11rem_1fr]">
          <nav aria-label="Settings sections" className="flex scroll-fade-effect-x scrollbar-none gap-1 overflow-x-auto border-b border-border p-3 @2xl:mask-none @2xl:flex-col @2xl:border-r @2xl:border-b-0">
            {SECTIONS.map((item) => (
              <Button
                key={item.id}
                variant={item.id === section ? "secondary" : "ghost"}
                size="sm"
                aria-current={item.id === section ? "true" : undefined}
                onClick={() => jumpTo(item.id)}
                className="shrink-0 justify-start"
              >
                {item.label}
              </Button>
            ))}
          </nav>
          <div ref={scrollRef} onScroll={onScroll} className="relative h-112 scroll-fade-effect-y scrollbar-none overflow-y-auto px-2 py-3 @lg:px-4">
            {SECTIONS.map((item) => (
              <section key={item.id} aria-labelledby={`${titleId}-${item.id}`} className="pb-4">
                <h3 id={`${titleId}-${item.id}`} data-section-id={item.id} className="px-3 pt-2 pb-1 text-sm font-semibold">
                  {item.label}
                </h3>
                <div className="flex flex-col gap-1">
                  {ROWS.filter((row) => row.section === item.id).map((row) => (
                    <SettingRow
                      key={row.id}
                      row={row}
                      value={values[row.id] ?? ""}
                      washed={washed === row.id}
                      onChange={(value) => setValues((current) => ({ ...current, [row.id]: value }))}
                    />
                  ))}
                </div>
              </section>
            ))}
          </div>
        </div>

        {phase !== "closed" ? (
          <span aria-hidden="true" className="absolute inset-0 z-20" onPointerDown={() => (phase === "open" ? close() : undefined)} />
        ) : null}
        {phase !== "closed" && boxes ? (
            <CommandPalette
              from={boxes.from}
              to={boxes.to}
              contentWidth={boxes.width}
              transition={reduceMotion ? INSTANT : phase === "flying" ? FLY : GROW}
              onSettled={settle}
              query={query}
              onQuery={(next) => {
                setQuery(next);
                setActive(0);
              }}
              results={results}
              active={Math.min(active, Math.max(0, results.length - 1))}
              onActive={setActive}
              onPick={pick}
              onClose={close}
            />
          ) : null}
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

