"use client";

import { motion, type Transition } from "motion/react";
import { type KeyboardEvent, useId, type CSSProperties } from "react";

import { Input } from "@/components/ui/input";
import { Kbd } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

import { SearchIcon } from "../icons";
import { type SettingRow, SECTIONS } from "./data";

/** A box inside the block, measured from its top left, with the corner radius it should take. */
export type PaletteBox = {
  top: number;
  left: number;
  width: number;
  height: number;
  borderRadius: number;
  opacity: number;
};

/** Props for the search palette. */
export interface CommandPaletteProps {
  from: PaletteBox;
  to: PaletteBox;
  /** The width of the open palette. The content keeps it while the box grows, so the edge reveals it. */
  contentWidth: number;
  transition: Transition;
  onSettled: () => void;
  query: string;
  onQuery: (query: string) => void;
  results: SettingRow[];
  active: number;
  onActive: (index: number) => void;
  onPick: (index: number) => void;
  onClose: () => void;
}

/**
 * The search palette. It grows out of the header field: place, size and
 * corner radius move on one spring while the results keep their final width,
 * so the growing edge uncovers them instead of reflowing them. Focus stays in
 * the input: arrows move the active result, Enter picks it, Escape closes.
 */
export function CommandPalette(props: CommandPaletteProps) {
  const { from, to, contentWidth, transition, onSettled, query, onQuery, results, active, onActive, onPick, onClose } = props;
  const listId = useId();
  const optionId = (index: number) => `${listId}-option-${index}`;

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (results.length === 0) return;
      const step = event.key === "ArrowDown" ? 1 : -1;
      onActive((active + step + results.length) % results.length);
    } else if (event.key === "Enter") {
      event.preventDefault();
      if (results[active]) onPick(active);
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      onClose();
    }
  };

  return (
    <motion.div
      role="dialog"
      aria-label="Search settings"
      initial={from}
      animate={to}
      transition={transition}
      onAnimationComplete={onSettled}
      className="absolute z-30 overflow-hidden border border-border bg-popover text-popover-foreground shadow-xl backdrop-blur-md"
    >
      <div
        // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
        style={{ "--content": `${contentWidth / 16}rem` } as CSSProperties}
        className="flex h-full w-(--content) max-w-full flex-col"
      >
        <div className="flex h-11 shrink-0 items-center gap-2 border-b border-border px-3">
          <SearchIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
          <Input
            autoFocus
            role="combobox"
            aria-expanded="true"
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={results[active] ? optionId(active) : undefined}
            aria-label="Search settings"
            placeholder="Search settings"
            value={query}
            onChange={(event) => onQuery(event.target.value)}
            onKeyDown={onKeyDown}
            className="flex-1"
          />
          <Kbd aria-hidden="true">Esc</Kbd>
        </div>
        <ul id={listId} role="listbox" aria-label="Matching settings" className="flex-1 scroll-fade-effect-y scrollbar-none overflow-y-auto p-1.5">
          {results.map((row, index) => {
            const selected = index === active;
            return (
              <li
                key={row.id}
                id={optionId(index)}
                role="option"
                aria-selected={selected}
                onPointerDown={(event) => event.preventDefault()}
                onPointerMove={() => onActive(index)}
                onClick={() => onPick(index)}
                className="relative isolate flex cursor-pointer items-center justify-between gap-3 rounded-lg px-3 py-2"
              >
                <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-lg", selected ? "bg-muted" : undefined)} />
                <span className="flex min-w-0 flex-col">
                  <span className="truncate text-sm font-medium">{row.label}</span>
                  <span className="truncate text-xs text-muted-foreground">{row.helper}</span>
                </span>
                <span className="shrink-0 text-xs text-muted-foreground">{SECTIONS.find((section) => section.id === row.section)?.label}</span>
              </li>
            );
          })}
          {results.length === 0 ? <li className="px-3 py-6 text-center text-sm text-muted-foreground">No setting matches “{query}”.</li> : null}
        </ul>
        <p role="status" className="sr-only">
          {results.length === 1 ? "1 setting found" : `${results.length} settings found`}
        </p>
      </div>
    </motion.div>
  );
}

