/** The rows whose label, helper, section or keywords hold every word of the query. */
export function searchRows(query: string) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return ROWS;
  return ROWS.filter((row) => {
    const section = SECTIONS.find((item) => item.id === row.section)?.label ?? "";
    const haystack = `${row.label} ${row.helper} ${section} ${row.keywords ?? ""}`.toLowerCase();
    return words.every((word) => haystack.includes(word));
  });
}

"use client";

import { useId } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Switch } from "@/components/motion/switch";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";

import type { SettingRow as Row } from "./data";

/** Props for one setting row. */
export interface SettingRowProps {
  row: Row;
  value: string;
  onChange: (value: string) => void;
  /** Washes the row with a tint that fades, after a search lands on it. */
  washed: boolean;
}

/**
 * A label and helper on the left and the row's control on the right. On a
 * narrow frame the control drops under the label.
 */
export function SettingRow({ row, value, onChange, washed }: SettingRowProps) {
  const id = useId();
  const labelId = `${id}-label`;
  const helperId = `${id}-helper`;
  const options = row.options ?? [];

  return (
    <div data-row-id={row.id} className="relative isolate flex flex-col gap-3 rounded-xl px-3 py-3.5 @lg:flex-row @lg:items-center @lg:justify-between">
      <span
        aria-hidden="true"
        className={cn(
          "absolute inset-0 -z-10 rounded-xl bg-chart-1/15 transition-opacity",
          washed ? "opacity-100 duration-150" : "opacity-0 duration-1000",
        )}
      />
      <div className="flex min-w-0 flex-col gap-0.5">
        <label id={labelId} htmlFor={row.kind === "text" || row.kind === "switch" ? id : undefined} className="text-sm font-medium">
          {row.label}
        </label>
        <span id={helperId} className="text-xs text-muted-foreground">
          {row.helper}
        </span>
      </div>
      <div className="shrink-0 @lg:w-56 @lg:[&>*]:ml-auto">
        {row.kind === "text" ? (
          <Input id={id} value={value} aria-describedby={helperId} onChange={(event) => onChange(event.target.value)} className="@lg:w-56" />
        ) : null}
        {row.kind === "switch" ? (
          <Switch id={id} aria-describedby={helperId} checked={value === "on"} onCheckedChange={(on) => onChange(on ? "on" : "off")} />
        ) : null}
        {row.kind === "select" ? (
          <Select value={value} onValueChange={onChange}>
            <SelectTrigger aria-labelledby={labelId} aria-describedby={helperId} className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {options.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : null}
        {row.kind === "segmented" ? (
          <div className="flex @lg:justify-end">
            <SegmentedControl aria-label={row.label} options={options} value={value} onValueChange={onChange} />
          </div>
        ) : null}
      </div>
    </div>
  );
}
